"""Image API settings and SDK calls; generated bytes never enter the model transcript."""

from __future__ import annotations

import asyncio
import base64
import binascii
import hashlib
import ipaddress
import socket
from typing import Literal
from urllib.parse import urljoin, urlsplit

import aiohttp
import httpx
from aiohttp.abc import ResolveResult
from aiohttp.resolver import ThreadedResolver
from openai import AsyncOpenAI
from openai.types.responses.tool_param import ImageGeneration
from pydantic import BaseModel, ConfigDict, Field, StrictBool, field_validator

from agent.errors import UserFacingError
from agent.media import IMAGE_LIMIT, image_mime
from agent.models.native_model import provider_http_options

IMAGE_SETTING_KEY = "models.image_generation"


class ImageSettings(BaseModel):
    model_config = ConfigDict(extra="forbid")
    enabled: StrictBool = False
    protocol: Literal["images", "responses"] = "images"
    base_url: str = Field(default="https://api.openai.com/v1", max_length=2000)
    model: str = Field(default="", max_length=200)
    size: str = Field(default="", max_length=32, pattern=r"^(|auto|[1-9][0-9]{1,4}x[1-9][0-9]{1,4})$")
    response_format: Literal["", "b64_json", "url"] = ""
    timeout_seconds: int = Field(default=180, ge=10, le=600)
    credential_required: StrictBool = False

    @field_validator("base_url")
    @classmethod
    def endpoint(cls, value: str) -> str:
        value = value.strip().rstrip("/")
        parsed = urlsplit(value)
        if (
            parsed.scheme not in {"http", "https"}
            or not parsed.hostname
            or parsed.username
            or parsed.password
            or parsed.query
            or parsed.fragment
        ):
            raise ValueError("Base URL must be HTTP(S), without credentials, query or fragment")
        _ = parsed.port
        # Users configure the API root, including /v1 if their service requires it.
        # Never guess a product from a port or silently rewrite its routing prefix.
        if parsed.path.endswith(("/images/generations", "/chat/completions", "/responses")):
            raise ValueError("Use the API base URL, not an individual endpoint")
        return value

    @field_validator("model")
    @classmethod
    def model_name(cls, value: str) -> str:
        return value.strip()

    def credential_reference(self) -> str:
        return "image-generation." + hashlib.sha256(self.base_url.encode()).hexdigest()

    def fingerprint(self) -> str:
        return hashlib.sha256(self.model_dump_json().encode()).hexdigest()


class _PublicResolver(ThreadedResolver):
    """Check the addresses actually handed to the download connector, not a separate DNS lookup."""

    async def resolve(
        self,
        host: str,
        port: int = 0,
        family: socket.AddressFamily = socket.AF_INET,
    ) -> list[ResolveResult]:
        addresses = await super().resolve(host, port, family)
        if any(not ipaddress.ip_address(item["host"]).is_global for item in addresses):
            raise UserFacingError("图片下载地址指向非公开网络，已拒绝访问；请让服务返回 Base64 图片。")
        return addresses


async def _download(url: str, endpoint: str) -> bytes:
    trusted = urlsplit(endpoint)
    for _ in range(4):
        target = urlsplit(url)
        if (
            target.scheme not in {"http", "https"}
            or not target.hostname
            or target.username
            or target.password
            or target.fragment
        ):
            raise UserFacingError("生图服务返回了不支持的图片地址。")
        same_origin = (target.scheme, target.hostname, target.port) == (
            trusted.scheme,
            trusted.hostname,
            trusted.port,
        )
        if not same_origin:
            try:
                address = ipaddress.ip_address(target.hostname)
            except ValueError:
                address = None
            if address is not None and not address.is_global:
                raise UserFacingError("图片下载地址指向非公开网络，已拒绝访问。")
        resolver = ThreadedResolver() if same_origin else _PublicResolver()
        try:
            # No API key, cookies, ambient netrc or proxy credentials follow an image URL.
            async with (
                aiohttp.ClientSession(
                    connector=aiohttp.TCPConnector(resolver=resolver),
                    cookie_jar=aiohttp.DummyCookieJar(),
                    timeout=aiohttp.ClientTimeout(total=30),
                    trust_env=False,
                ) as client,
                client.get(url, allow_redirects=False) as response,
            ):
                if response.status in {301, 302, 303, 307, 308}:
                    location = response.headers.get("Location")
                    if not location:
                        raise UserFacingError("图片下载重定向缺少目标地址。")
                    url = urljoin(url, location)
                    continue
                response.raise_for_status()
                data = bytearray()
                async for chunk in response.content.iter_chunked(65536):
                    data.extend(chunk)
                    if len(data) > IMAGE_LIMIT:
                        raise UserFacingError("生成图片超过 16 MiB，未保存；请降低输出尺寸。")
                return bytes(data)
        finally:
            await resolver.close()
    raise UserFacingError("图片下载重定向次数过多。")


async def generate_image(settings: ImageSettings, prompt: str, api_key: str) -> tuple[bytes, str]:
    body: dict[str, object] = {}
    if settings.size:
        body["size"] = settings.size
    if settings.response_format:
        body["response_format"] = settings.response_format
    # Each invocation owns and closes its transport. Cancellation cannot close
    # another run's client; retries are off because generation may be billable.
    async with (
        asyncio.timeout(settings.timeout_seconds),
        httpx.AsyncClient(
            timeout=settings.timeout_seconds,
            **provider_http_options(settings.base_url, asynchronous=True),
        ) as transport,
        AsyncOpenAI(
            api_key=api_key or "local-no-key",
            base_url=settings.base_url,
            http_client=transport,
            max_retries=0,
        ) as client,
    ):
        encoded, url = "", ""
        if settings.protocol == "responses":
            tool: ImageGeneration = {"type": "image_generation"}
            if settings.size:
                tool["size"] = settings.size
            response = await client.responses.create(
                model=settings.model,
                input=prompt,
                tools=[tool],
                tool_choice={"type": "image_generation"},
                max_tool_calls=1,
                parallel_tool_calls=False,
                store=False,
            )
            outputs = [item for item in response.output if item.type == "image_generation_call"]
            if len(outputs) != 1 or outputs[0].status != "completed":
                raise UserFacingError("模型未返回一张完整的图片；请检查服务是否支持 Responses 生图工具。")
            encoded = outputs[0].result or ""
        else:
            result = await client.images.generate(model=settings.model, prompt=prompt, n=1, extra_body=body)
            if not result.data:
                raise UserFacingError("生图服务未返回图片。")
            encoded, url = result.data[0].b64_json or "", result.data[0].url or ""
        if encoded:
            if len(encoded) > ((IMAGE_LIMIT + 2) // 3) * 4:
                raise UserFacingError("生成图片超过 16 MiB，未保存；请降低输出尺寸。")
            try:
                data = base64.b64decode(encoded, validate=True)
            except (ValueError, binascii.Error) as exc:
                raise UserFacingError("生图服务返回的图片编码无效。") from exc
        elif url:
            data = await _download(url, settings.base_url)
        else:
            raise UserFacingError("生图服务未返回可保存的图片。")
    mime = image_mime(data)
    if not mime or len(data) > IMAGE_LIMIT:
        raise UserFacingError("返回内容不是受支持的图片，或超过 16 MiB，未保存。")
    return data, mime
